head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldods17010";

// TODO Stage2: 세션 키 실환경 확인(회신 11항) — session.user.kclicUsrTpId

// 세션 사용자 결선 (어휘 session_attribute 1건 — gcc $c.session.getUserInfo)

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_sessionFill();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldods17010.onpageload' });
    }
};

/**
 * @method
 * @name init_sessionFill
 * @description 초기화 — session Fill
 * @returns {void}
 * @hidden N
 */
scwin.init_sessionFill = function () {
    const names = ["kclicUsrTpId"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldods17010' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

// [A] 초기 목록 미해결 — jldods17010: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_list_onclick
 * @description 「목록으로」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_list_onclick = function(e){
    try {
        scwin.list()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods17010.btn_list_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name list
 * @description list 처리
 * @returns {void}
 * @hidden N
 */
scwin.list = function () {
    if ((String(($c.session.getUserInfo("kclicUsrTpId")) == null ? '' : ($c.session.getUserInfo("kclicUsrTpId"))).indexOf('$' + '{') >= 0 ? '' : String(($c.session.getUserInfo("kclicUsrTpId")) == null ? '' : ($c.session.getUserInfo("kclicUsrTpId")))) === 'LIST_CORP_DISCLS') {
        $('#ipt_SCREN_ID', $('#searchForm')).val("/jldods17001/jldods17001.xml");
    } else {
        $('#ipt_SCREN_ID', $('#searchForm')).val("/jldods17000/jldods17000.xml");
    }
    $('#ipt_SCREN_PROCES_TP_CD', $('#searchForm')).val("01");
    $('#ipt_method', $('#searchForm')).val("readUserList");
    $('#searchForm').submit();
};
